function colorChannels(hex:string){const value=hex.trim().replace(/^#/,'');const full=value.length===3?value.split('').map(v=>v+v).join(''):value;return [0,2,4].map(i=>parseInt(full.slice(i,i+2),16))}
function colorLuminance(channels:number[]){const [r,g,b]=channels.map(value=>value/255).map(value=>value<=0.04045?value/12.92:((value+0.055)/1.055)**2.4);return r*0.2126+g*0.7152+b*0.0722}
function readableAccent(color:string,backgrounds:string[],minimum:number){const channels=colorChannels(color),surfaces=backgrounds.map(value=>colorLuminance(colorChannels(value)));const target=surfaces.reduce((a,b)=>a+b,0)/surfaces.length<0.5?255:0;for(let step=0;step<=50;step++){const candidate=channels.map(value=>Math.round(value+(target-value)*step/50));const light=colorLuminance(candidate);if(surfaces.every(surface=>(Math.max(surface,light)+0.05)/(Math.min(surface,light)+0.05)>=minimum))return '#'+candidate.map(value=>value.toString(16).padStart(2,'0')).join('')}return target?'#ffffff':'#000000'}
