function Modal({title,children,close,wide=false}:{title:string;children:ReactNode;close:()=>void;wide?:boolean}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;ref.current?.focus();const fn=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'){const items=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input,textarea,select,a[href],[tabindex="0"]');if(!items?.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===ref.current)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',fn);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',fn);document.body.style.overflow=old;previous?.focus();};},[]);return <div className="modal-backdrop" onClick={e=>e.target===e.currentTarget&&close()}><div role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref} className={`modal ${wide?'wide':''}`}><div className="modal-header"><h2>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={close}><X size={20}/></button></div><div className="modal-body">{children}</div></div></div>}
const localDateKey=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const validKits=(value:unknown):Kit[]=>Array.isArray(value)?value.flatMap(item=>{try{return [validateKit(item)]}catch{return []}}):[];
function readSyncedIds(owner:string){try{const value:unknown=JSON.parse(localStorage.getItem('matrix-synced-kits-'+owner)||'[]');return new Set(Array.isArray(value)?value.filter((id):id is string=>typeof id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(id)):[])}catch{return new Set<string>()}}
function reconcileLibrary(local:Kit[],cloud:Kit[],cloudIds:Set<string>,acknowledged:Set<string>){const retained=local.filter(kit=>!acknowledged.has(kit.id)||cloudIds.has(kit.id));const remote=new Map(cloud.map(kit=>[kit.id,kit]));const merged=new Map(retained.map(kit=>[kit.id,kit]));cloud.forEach(kit=>{if(!merged.has(kit.id)||merged.get(kit.id)!.updatedAt<=kit.updatedAt)merged.set(kit.id,kit)});return {kits:[...merged.values()],pending:retained.filter(kit=>!kit.demo&&(!remote.has(kit.id)||kit.updatedAt>remote.get(kit.id)!.updatedAt))}}
const jsonRequest=async<T,>(path:string,options?:RequestInit):Promise<T>=>{const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),path==='/api/ai'?100000:15000);try{const r=await fetch(path,{...options,signal:options?.signal||controller.signal,headers:{'Content-Type':'application/json',...options?.headers}});const data=await r.json() as {error?:string};if(!r.ok)throw new Error(data.error||'Something went wrong. Please try again.');return data as T;}catch(error){if(controller.signal.aborted)throw new Error('The connection took too long. Your saved device data is still available.');throw error;}finally{clearTimeout(timer)}};
